import numpy as np, time

def f_outer(a,b): return np.outer(a,b)
def f_mouter(a,b): return np.multiply.outer(a,b)
def f_b1(a,b): return np.multiply(a[:,None], b[None,:])
def f_b2(a,b): return np.multiply(a[:,None], b)
def f_out(a,b):
    out=np.empty((a.shape[0], b.shape[0]), dtype=np.result_type(a,b))
    return np.multiply(a[:,None], b, out=out)

funcs=[f_outer,f_mouter,f_b1,f_b2,f_out]
for n in [1,2,3,5,10,30,100,300,1000,3000]:
    a=np.random.rand(n); b=np.random.rand(n)
    reps=max(1, min(20000, int(2e7/(n*n))))
    print('\nn', n, 'reps', reps)
    for f in funcs:
        y=f(a,b)
        assert np.allclose(y, np.outer(a,b))
        t=time.perf_counter()
        for _ in range(reps): f(a,b)
        dt=time.perf_counter()-t
        print(f.__name__, dt)
